// Application-derived record values must conform to their canonical declared types.
{
 const matches=(type,value)=>{switch(type){case 'STRING':case 'REFERENCE':return typeof value==='string';case 'INTEGER':return Number.isInteger(value);case 'NUMBER':return typeof value==='number'&&Number.isFinite(value);case 'BOOLEAN':return typeof value==='boolean';case 'STRING_ARRAY':case 'REFERENCE_ARRAY':return Array.isArray(value)&&value.every(item=>typeof item==='string');case 'OBJECT':return value!==null&&typeof value==='object'&&!Array.isArray(value);case 'OBJECT_ARRAY':return Array.isArray(value)&&value.every(item=>item!==null&&typeof item==='object'&&!Array.isArray(item));default:return false;}};
 const mismatches=[];
 for(const [collection,definition] of Object.entries(schema.RECORD_SCHEMAS)){for(const record of (p.projectData?.[collection]||[])){for(const [fieldName,fieldDefinition] of Object.entries(definition.fieldDefinitions||{})){if(fieldDefinition.producer!=='APPLICATION')continue;const fields=record.fields&&typeof record.fields==='object'?record.fields:record;if(!Object.prototype.hasOwnProperty.call(fields,fieldName))continue;const value=fields[fieldName];if(value===null&&fieldDefinition.nullable)continue;if(!matches(fieldDefinition.valueType,value))mismatches.push(`${collection}.${fieldName}: declared ${fieldDefinition.valueType}, actual ${Array.isArray(value)?'ARRAY':typeof value}, value=${JSON.stringify(value)}`);}}}
 assert(!mismatches.length,'Application-derived type mismatches:\n'+mismatches.join('\n'));
}

for(const [collection,definition] of Object.entries(schema.RECORD_SCHEMAS))for(const record of p.projectData[collection]||[]){if(record.recordSha256)assert(record.recordSha256===hash.recordSha256(record),`${collection} ${engine.recordId(record,collection)} has a stale recordSha256.`);if(record.contentSha256)assert(record.contentSha256===hash.contentRecordSha256(record,definition.idField),`${collection} ${engine.recordId(record,collection)} has a stale contentSha256.`);}
